package store

import (
	"testing"
)

// TestFindOrCreateOrg_ReturnsGeneratedID pins the invariant the whole re-key
// rests on: organizations.id is generated by Postgres (gen_random_uuid()), so
// the struct handed back from a create must carry that value, not the zero
// string.
//
// This is not hypothetical. Every id-derived key in the store —
// SeedDevSubscription's "dev-sub-<orgID>" primary key, the tenant-scoping
// WHERE clause — silently collapses onto a single shared value if the id comes
// back empty, which surfaces far away as a duplicate-key violation rather than
// as "the id is missing".
func TestFindOrCreateOrg_ReturnsGeneratedID(t *testing.T) {
	db := testOpen(t)

	created, err := db.FindOrCreateOrg("acme-generated-id")
	if err != nil {
		t.Fatalf("FindOrCreateOrg: %v", err)
	}
	if created.ID == "" {
		t.Fatal("FindOrCreateOrg returned an empty ID; the DB-generated UUID was not read back")
	}

	// A second org must not reuse the first one's id.
	other, err := db.FindOrCreateOrg("globex-generated-id")
	if err != nil {
		t.Fatalf("FindOrCreateOrg (second): %v", err)
	}
	if other.ID == created.ID {
		t.Fatalf("two orgs share id %q", created.ID)
	}

	// Re-finding an existing org returns the same id rather than minting one.
	again, err := db.FindOrCreateOrg("acme-generated-id")
	if err != nil {
		t.Fatalf("FindOrCreateOrg (refind): %v", err)
	}
	if again.ID != created.ID {
		t.Fatalf("refind id = %q, want %q", again.ID, created.ID)
	}

	// And the id round-trips through a lookup.
	fetched, err := db.GetOrgByID(created.ID)
	if err != nil {
		t.Fatalf("GetOrgByID: %v", err)
	}
	if fetched.Name != "acme-generated-id" {
		t.Fatalf("GetOrgByID name = %q, want acme-generated-id", fetched.Name)
	}
}
